{
  "tasks": [
    {
      "task_id": "T1",
      "title": "各城市已完成订单销售额汇总及排序",
      "business_question": "统计各城市已完成订单的销售额总和，并按销售额升序排列。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标“统计各城市已完成订单的销售额总和并按升序排列”，删除后无法支持该决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "total_sales",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
